+		type,
+		title = null,
+		linked = true,
+		stopPropagation = false,
+		class: className = ''
+	}: Props = $props();
+
+	let normalized = $derived(normalizeRef(rawRef));
+	let short = $derived(shortRef(rawRef));
+	let href = $derived(refHref(type, rawRef, base));
+
+	function handleClick(e: MouseEvent) {
